/**
 * Paging, and the rule that `select` is mandatory.
 *
 * `retrieveMultipleRecordsAsync` returns one page plus a `skipToken`. The canvas app had no
 * equivalent: `ClearCollect` simply stopped at
 * `DefaultConnectedDataSourceMaxGetRowsCount: 2000` and gave no indication it had truncated.
 * `fetchAll` follows the token, so a project with more cost rows than the old cap does not
 * quietly lose them.
 */
import type { IOperationOptions, IOperationResult } from "@microsoft/power-apps/data";
import { getClient } from "@microsoft/power-apps/data";
// Generated by `pac code add-data-source`; the same import the generated services use.
import { dataSourcesInfo } from "../../.power/schemas/appschemas/dataSourcesInfo";
import { DataError, RecordGoneError, asRecordGone, unwrap } from "@/platform/errors";
import { trace } from "@/platform/telemetry";
import { guid } from "./odata";

export { RecordGoneError };

/** One page of a table. */
type PageFn<T> = (options: IOperationOptions) => Promise<IOperationResult<T[]>>;

export interface FetchAllOptions extends Omit<IOperationOptions, "filter"> {
  /**
   * `$select` is required, not optional. Dataverse returns EVERY column without it — on
   * `vsb_projects` that is 112 columns per row — and the formatted-value annotations on top.
   */
  select: string[];
  /**
   * Optional, and `undefined` means NO `$filter` at all.
   *
   * The builders in `./odata` return `undefined` rather than `""` for exactly this reason:
   * an empty `$filter=` is a 400, so the key is stripped below instead of forwarded blank.
   */
  filter?: string | undefined;
  /** Safety valve. Exceeding it is a bug in the caller's filter, so it traces loudly. */
  maxPages?: number;
}

/** Drops keys whose value is undefined, so `{filter: undefined}` never becomes `$filter=`. */
function compact(options: Record<string, unknown>): IOperationOptions {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(options)) if (v !== undefined) out[k] = v;
  return out as IOperationOptions;
}

const DEFAULT_MAX_PAGES = 50;
const DEFAULT_PAGE_SIZE = 500;

export async function fetchAll<T>(
  operation: string,
  page: PageFn<T>,
  options: FetchAllOptions,
): Promise<T[]> {
  const { maxPages = DEFAULT_MAX_PAGES, ...query } = options;
  const rows: T[] = [];
  let skipToken: string | undefined;
  let pages = 0;

  do {
    const result = await page(compact({
      maxPageSize: DEFAULT_PAGE_SIZE,
      ...query,
      ...(skipToken ? { skipToken } : {}),
    }));
    rows.push(...unwrap(result, `${operation} (page ${pages + 1})`));
    skipToken = result.skipToken;
    pages += 1;
    if (pages >= maxPages && skipToken) {
      // Truncating silently is exactly the canvas behaviour this function exists to avoid,
      // so say so rather than returning a plausible-looking short list.
      trace(
        "error",
        `${operation} stopped after ${pages} pages with more rows available — the filter is too broad`,
        { rows: rows.length },
      );
      break;
    }
  } while (skipToken);

  return rows;
}

/** A single page, for the cases where one page is genuinely all that is wanted. */
export async function fetchPage<T>(
  operation: string,
  page: PageFn<T>,
  options: FetchAllOptions,
): Promise<T[]> {
  const { maxPages: _ignored, ...query } = options;
  return unwrap(
    await page(compact({ maxPageSize: DEFAULT_PAGE_SIZE, ...query })),
    operation,
  );
}

/* ═══════════════════════════════════════════════════════════════ writes ══ */

/**
 * A delete whose failure is observable.
 *
 * The generated services declare `delete(id): Promise<void>` and **discard** the
 * `IOperationResult` the SDK hands back, so a Dataverse refusal — a 403 from row-level
 * security, a cascade the server would not perform — resolves exactly like a success. The SDK
 * never throws for a failed data call (see `platform/errors.ts`), so there is nothing else to
 * catch: the row stays, the screen says it went, and the user finds out later.
 *
 * `vsb_projects` is the one table where the canvas app itself refused to ignore that: the
 * delete is wrapped in `IfError` with an error notification. Reproducing that behaviour needs
 * the result, so this goes to the client directly — the same reason `countedPage` below does,
 * and for the same kind of gap in pac output, which must not be hand-edited.
 */
export async function deleteRecord(
  operation: string,
  tableName: string,
  recordId: string,
): Promise<void> {
  const client = getClient(dataSourcesInfo);
  unwrap(await client.deleteRecordAsync(tableName, recordId), operation);
}

/* ══════════════════════════════════════════════════════ counted paging ══ */

/**
 * A page of rows plus the server-side total, paged with a SKIP TOKEN.
 *
 * **Dataverse does not support `$skip`.** It answers
 * `{"code":"0x80060888","message":"Skip Clause is not supported in CRM"}`. Paging is
 * forward-only through `@odata.nextLink`, which the SDK surfaces as `skipToken` on both the
 * request and the result. That is why this walks rather than jumps, and it is also why the
 * canvas pager only ever had First / Previous / Next and no page-number box.
 *
 * Tokens are cached per query signature so Previous is free and a re-render does not re-walk.
 * A shared link that names page 3 walks pages 1 and 2 to get there — two extra round trips,
 * once, which is the honest cost of a forward-only cursor.
 *
 * Why not the generated service: `IGetAllOptions` in `src/generated/models/CommonModels.ts`
 * declares no `count`, though the SDK's `IOperationOptions` does and the runtime honours it.
 * That file is pac output and must not be hand-edited.
 *
 * `@odata.count` is capped at 5000 by the platform, so a filtered set larger than that
 * reports exactly 5000. At 1,129 projects that is far off, but it is a real ceiling.
 */
export interface CountedPage<T> {
  rows: T[];
  /** `@odata.count` for the whole filtered set. Capped at 5000 by the platform. */
  totalRows: number;
  /** 1-based, and clamped to what actually exists. */
  page: number;
  /** True when the server returned a token for a further page. */
  hasNext: boolean;
}

/** Token caches, keyed by query signature. `tokens[0]` is always undefined — page 1. */
const tokenCache = new Map<string, (string | undefined)[]>();

/** Discards the walk when the filter or sort changes; a stale token returns the wrong rows. */
export function resetPageTokens(signature?: string): void {
  if (signature === undefined) tokenCache.clear();
  else tokenCache.delete(signature);
}

export interface CountedPageRequest extends FetchAllOptions {
  /** Rows per page. */
  top: number;
  /** 1-based. */
  page: number;
  /**
   * Identifies the query the tokens belong to — the filter and the sort. Two different
   * filters must never share a token.
   */
  signature: string;
}

export async function countedPage<T>(
  operation: string,
  tableName: string,
  request: CountedPageRequest,
): Promise<CountedPage<T>> {
  const { maxPages: _ignored, page, signature, ...query } = request;
  const client = getClient(dataSourcesInfo);
  const wanted = Math.max(1, Math.floor(page) || 1);

  const tokens = tokenCache.get(signature) ?? [undefined];
  tokenCache.set(signature, tokens);

  const fetchAt = async (index: number) => {
    const result = await client.retrieveMultipleRecordsAsync<T>(
      tableName,
      compact({ ...query, count: true, skipToken: tokens[index] }),
    );
    const rows = unwrap(result, `${operation} (page ${index + 1})`);
    // Remember the token that reaches the NEXT page, so Previous never re-walks.
    if (result.skipToken) tokens[index + 1] = result.skipToken;
    return { rows, totalRows: result.count ?? rows.length, next: result.skipToken };
  };

  let index = 0;
  let current = await fetchAt(0);

  // Walk forward to the requested page, stopping early if the data runs out.
  while (index + 1 < wanted && current.next) {
    index += 1;
    current = await fetchAt(index);
  }

  return {
    rows: current.rows,
    totalRows: current.totalRows,
    page: index + 1,
    hasNext: Boolean(current.next),
  };
}

/* ══════════════════════════════════════════════════ guarded single-row update ══ */

/**
 * Runs an SDK call and returns its result UNCHANGED (`skipToken` included, so `fetchAll` keeps
 * following it past 500 rows); a THROWN error becomes a `DataError(operation)`. Already-typed
 * errors pass through. `success: false` is left to the caller (`fetchAll` unwraps it per page).
 */
export async function guardedResult<T>(operation: string, call: () => Promise<IOperationResult<T>>): Promise<IOperationResult<T>> {
  try {
    return await call();
  } catch (error) {
    throw error instanceof DataError ? error : new DataError(operation, error);
  }
}

/**
 * Runs an SDK call; a THROWN error becomes a `DataError(operation)` and `success: false` is
 * unwrapped into one. Already-typed errors pass through.
 */
export async function guardedCall<T>(operation: string, call: () => Promise<IOperationResult<T>>): Promise<T> {
  return unwrap(await guardedResult(operation, call), operation);
}

/** The slice of the SDK client `updateRecordIfExists` uses (injectable for tests). */
export interface GuardedUpdateClient {
  retrieveMultipleRecordsAsync<T>(table: string, options?: IOperationOptions): Promise<IOperationResult<T[]>>;
  updateRecordAsync<TIn, TOut>(table: string, id: string, record: TIn): Promise<IOperationResult<TOut>>;
}

export interface UpdateIfExistsOptions {
  /**
   * The table's primary-key column. Defaults to `primaryKey` in the generated `dataSourcesInfo`.
   * With neither, the update is refused (fail closed) rather than sent unguarded.
   */
  primaryKey?: string;
  client?: () => GuardedUpdateClient;
}

/** `primaryKey` of a registered data source, or undefined. */
export function primaryKeyOf(tableName: string): string | undefined {
  const info = (dataSourcesInfo as Record<string, { primaryKey?: string } | undefined>)[tableName];
  return info?.primaryKey || undefined;
}

/**
 * Upsert guard — a single-row update that does not silently recreate a deleted row.
 *
 * With `@microsoft/power-apps` 1.3.1 (this app's SDK) `updateRecordAsync` is sent as
 * `PATCH <set>(<id>)` with NO `If-Match` header, and the public API has no headers parameter. A
 * Web API PATCH without `If-Match: *` is an UPSERT, so updating a row another user had just deleted
 * would create a NEW row holding only the patched columns. On 1.3.1 the existence read below IS the
 * guard: the row is read by primary key first and, when it is gone, `RecordGoneError` is thrown with
 * nothing sent. (A delete landing between the read and the PATCH is the remaining, narrow race;
 * a later SDK that sends `If-Match: *` closes it, and a 404 is then mapped by `asRecordGone`.)
 *
 * Any other failed read or PATCH surfaces as a `DataError`, never as "gone". Cost: one small GET
 * per single-row update.
 */
export async function updateRecordIfExists<TFields, TResult = unknown>(
  operation: string,
  tableName: string,
  recordId: string,
  fields: TFields,
  options: UpdateIfExistsOptions = {},
): Promise<TResult> {
  const primaryKey = options.primaryKey ?? primaryKeyOf(tableName);
  if (!primaryKey) {
    throw new DataError(operation, `no primary key is known for ${tableName}; refusing an unguarded update`);
  }
  let id: string;
  try {
    id = guid(recordId);
  } catch (error) {
    throw new DataError(operation, error);
  }
  const client = options.client ?? (() => getClient(dataSourcesInfo) as unknown as GuardedUpdateClient);

  const found = await guardedCall(`${operation} (existence check)`, () =>
    client().retrieveMultipleRecordsAsync<Record<string, unknown>>(tableName, {
      select: [primaryKey],
      filter: `${primaryKey} eq ${id}`,
      maxPageSize: 1,
    }),
  );
  if (found.length === 0) throw new RecordGoneError(operation, tableName, id);

  try {
    return await guardedCall(operation, () => client().updateRecordAsync<TFields, TResult>(tableName, id, fields));
  } catch (error) {
    throw asRecordGone(error, operation, tableName, id);
  }
}
